import{_ as a,o as i,c as t,a5 as r}from"./chunks/framework.BF53ZjCA.js";const u=JSON.parse('{"title":"GIA 4Cs (Diamond)","description":"","frontmatter":{"title":"GIA 4Cs (Diamond)","grading":"diamond-4cs"},"headers":[],"relativePath":"grading/diamond-4cs.md","filePath":"grading/diamond-4cs.md","lastUpdated":1790876393000}'),n={name:"grading/diamond-4cs.md"};function s(o,e,l,d,c,m){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="gia-4cs-diamond" tabindex="-1">GIA 4Cs (Diamond) <a class="header-anchor" href="#gia-4cs-diamond" aria-label="Permalink to &quot;GIA 4Cs (Diamond)&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>A diamond-grading framework established by GIA in 1953 and widely adopted. Four independent measurements—carat, color, clarity, cut—jointly determine a polished diamond&#39;s market value.</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-diamond-4cs-en"><p class="gem-identification-boundary__eyebrow">GRADING BOUNDARY</p><h2 id="identification-boundary-diamond-4cs-en">Boundary &amp; Safety</h2><p>This page explains 4C terms in standard diamond reports as an introductory description framework; D–Z is not the complete colour language for every coloured diamond context. The 4Cs alone do not prove natural/synthetic status, treatment, origin, or price. </p></aside><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Carat (ct): 1 ct = 0.2 g; 1 point = 0.01 ct. Weight is a measurement, not a universal price or rarity formula.</li><li>Color: D–Z scale, only the yellow/brown tint. D = colorless; Z = light.</li><li>Clarity: FL–I3 has 11 grades under 10×; inclusions and blemishes determine the grade.</li><li>Cut: Excellent → Poor. Proportions, symmetry, polish, brightness, fire, and scintillation must be read together.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Grade</th><th>Note</th></tr></thead><tbody><tr><td>diamond</td><td>D/IF/Excellent</td><td>Report-field example; not an auction grade</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page explains grading descriptions and report terms; the sources document the knowledge basis and do not make this page sufficient for grading, valuing, identifying, or determining the origin of a specific specimen.</p><ul><li><a href="https://www.gia.edu/diamond-quality-factor" target="_blank" rel="noreferrer">GIA: Diamond Quality Factors</a><span>Diamond quality factors including color, clarity, cut, and carat weight; not a price formula</span><small>Open source ↗</small></li><li><a href="https://4cs.gia.edu/en-us/diamond-clarity/" target="_blank" rel="noreferrer">GIA 4Cs: Diamond Clarity</a><span>Introductory explanation of FL–I3 clarity grades and the 10× observation condition</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/value-factors-design-cut-quality-colored-gemstone-value-factors" target="_blank" rel="noreferrer">GIA: Colored Gemstone Value Factors</a><span>Colour, cut, clarity, durability, and market factors vary by gemstone species</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/UK-EN/emerald-quality-factor" target="_blank" rel="noreferrer">GIA: Emerald Quality Factors</a><span>Species-specific context for emerald colour, transparency, inclusions, and treatment</span><small>Open source ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA: Analytical Methods Used in Geographic Origin Determination</a><span>Origin opinions use multiple evidence types and may remain inconclusive</span><small>Open source ↗</small></li><li><a href="https://www.ftc.gov/news-events/topics/tools-consumers/jewelry-guides" target="_blank" rel="noreferrer">FTC: Jewelry, Precious Metals, and Pewter Industries Guides</a><span>US consumer and marketing disclosure guidance; not automatically the law of every jurisdiction</span><small>Open source ↗</small></li></ul></aside><aside class="gem-reference-block gem-evidence-ledger" aria-labelledby="gem-evidence-title-diamond-4cs-en"><p class="gem-reference-block__eyebrow">EVIDENCE MAP</p><h2 id="gem-evidence-title-diamond-4cs-en">Evidence map for this page</h2><p class="gem-reference-block__intro">Claims are mapped to references and labelled with their evidence status in this knowledge base.</p><ul><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">Source-supported</strong><span>The 4Cs describe diamond quality; they are not an independent price formula or proof of authenticity.</span><small>GIA: Diamond Quality Factors</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--source-supported">Source-supported</strong><span>Diamond clarity grades must be understood with the specified observation conditions, inclusions, and blemishes.</span><small>GIA 4Cs: Diamond Clarity</small></li><li><strong class="gem-evidence-ledger__status gem-evidence-ledger__status--teaching-summary">Teaching summary</strong><span>Cut performance is not determined by proportion alone; brightness, scintillation, symmetry, polish, and durability also matter.</span><small>GIA: Diamond Quality Factors</small></li></ul></aside><p><em>See the <a href="./intro.html">grading overview</a>.</em></p>',11)])])}const g=a(n,[["render",s]]);export{u as __pageData,g as default};
